beforeExample:
import java.util.Objects;
class Example {
    String[] array1 = new String[]{"a", "b"};
    String[] array2 = new String[]{"a", "b"};
    String text1 = "hello";
    Object obj = new Object();

    void test() {
        // This should be transformed: comparing array content
        if (array1.equals(array2)) {
            System.out.println("Array reference equals");
        }

        // This should NOT be transformed: comparing a String
        if (text1.equals("world")) {
            System.out.println("String equals");
        }

        // This should NOT be transformed: comparing non-array Object
        if (obj.equals(array1)) {
            System.out.println("Object equals array");
        }
    }
}

afterExample:
import java.util.Arrays;
import java.util.Objects;
class Example {
    String[] array1 = new String[]{"a", "b"};
    String[] array2 = new String[]{"a", "b"};
    String text1 = "hello";
    Object obj = new Object();

    void test() {
        // This should be transformed: comparing array content
        if (java.util.Arrays.equals(array1, array2)) {
            System.out.println("Array reference equals");
        }

        // This should NOT be transformed: comparing a String
        if (text1.equals("world")) {
            System.out.println("String equals");
        }

        // This should NOT be transformed: comparing non-array Object
        if (obj.equals(array1)) {
            System.out.println("Object equals array");
        }
    }
}

